function swipeToken(address,dir){var c=S.candidates.find(function(x){return x.address===address});if(!c)return;var prevDecision=S.evaluations[address]&&S.evaluations[address].decision||null,prevDismissed=S.dismissed[address]||null,logTime=null;if(dir==='left'){S.dismissed[address]=Date.now();if(S.evaluations[address])S.evaluations[address].decision='REJECTED';logTime=log('REJECTED',c.symbol,'Swiped left from the opportunity deck.');save()}else{sessionReviewed[address]=Date.now()}lastSwipe={address:address,dir:dir,prevDecision:prevDecision,prevDismissed:prevDismissed,logTime:logTime,symbol:c.symbol};showUndo();render();if(dir==='right')setTimeout(function(){openReview(address)},80)}
