function bindSwipe(){var card=$('#heroSwipeCard');if(!card)return;var sx=0,sy=0,dx=0,drag=false,moved=false;card.onpointerdown=function(e){if(e.target.closest('button'))return;sx=e.clientX;sy=e.clientY;dx=0;drag=true;moved=false;card.classList.add('dragging');try{card.setPointerCapture(e.pointerId)}catch(_){}};card.onpointermove=function(e){if(!drag)return;var x=e.clientX-sx,y=e.clientY-sy;if(Math.abs(y)>Math.abs(x)&&Math.abs(y)>12){drag=false;card.classList.remove('dragging');card.style.transform='';return}dx=x;moved=moved||Math.abs(dx)>7;var rot=dx/18;card.style.transform='translateX('+dx+'px) rotate('+rot+'deg)';var op=Math.min(1,Math.abs(dx)/95);$('#leftStamp').style.opacity=dx<0?op:0;$('#rightStamp').style.opacity=dx>0?op:0};card.onpointerup=function(){if(!drag)return;drag=false;card.classList.remove('dragging');if(Math.abs(dx)>=85){var dir=dx<0?'left':'right';card.style.transform='translateX('+(dx<0?-620:620)+'px) rotate('+(dx<0?-18:18)+'deg)';card.style.opacity='0';setTimeout(function(){swipeToken(card.dataset.swipe,dir)},180)}else{card.style.transform='';$('#leftStamp').style.opacity=0;$('#rightStamp').style.opacity=0;if(!moved)openReview(card.dataset.swipe)}};card.onpointercancel=function(){drag=false;card.classList.remove('dragging');card.style.transform='';if($('#leftStamp'))$('#leftStamp').style.opacity=0;if($('#rightStamp'))$('#rightStamp').style.opacity=0}}

