function approve(c){c=S.candidates.find(function(x){return x.address===c.address});var reason=approvalReason(c);if(reason){toast(reason);return}if(lastSwipe&&lastSwipe.address===c.address){lastSwipe=null;showUndo()}S.positions.push({address:c.address,pairAddress:c.pair&&c.pair.pairAddress||null,poolProgram:c.pool&&c.pool.program||null,decimals:c.decimals===undefined?null:c.decimals,symbol:c.symbol,name:c.name,amount:Math.min(S.size,MAXSIZE),entry:c.price,current:c.price,opened:Date.now(),dayDate:day(),dayBasis:c.price,setup:c.setup,entryLiquidity:c.m.liq,remainingPct:1,realizedPnl:0,dayRealized:0,peak:c.price,stopPct:EXIT_STOP,t1Hit:false,t2Hit:false,trailActive:false,lastPriceAt:c.observedAt,stale:false,exitSignal:'WATCHING'});if(S.evaluations[c.address])S.evaluations[c.address].decision='APPROVED';log('APPROVED',c.symbol,money(S.size)+' simulated tracking started at '+price(c.price)+' with EXIT engine armed. No wallet transaction sent.');save();activeReview=null;reviewEpoch++;$('#backdrop').classList.add('hidden');render();toast(c.symbol+' tracking started — EXIT engine armed.')}

